.map-panel-backdrop{z-index:2147483647;align-items:center;justify-content:center;padding:24px;background:#10182e66;backdrop-filter:blur(3px)}.map-detail-panel.notes-card{width:min(620px,100%);height:auto;max-height:calc(100dvh - 48px);padding:0!important;overflow:hidden;border-radius:24px!important;box-shadow:0 24px 80px #10182e40}.map-panel-section{display:flex;flex-direction:column;max-height:calc(100dvh - 48px);min-height:0}.map-panel-header{display:flex;gap:14px;align-items:center;padding:24px;border-bottom:1px solid var(--border-glass,#dbe1ec);flex-shrink:0;background:linear-gradient(110deg,color-mix(in srgb,var(--folder-color) 7%,transparent),transparent)}.map-panel-emblem{width:44px;height:44px;border-radius:14px;display:grid;place-items:center;flex:none;background:color-mix(in srgb,var(--folder-color) 12%,transparent);color:var(--folder-color);font-size:19px}.map-panel-heading{min-width:0;flex:1}.map-panel-heading h2{margin:0;font-size:18px!important;line-height:1.35;overflow-wrap:anywhere}.map-panel-heading p{font-size:12px;color:var(--text-muted);margin:4px 0 0;overflow-wrap:anywhere}.map-panel-close{display:grid;place-items:center;width:36px;height:36px;flex:none;border:1px solid var(--border-glass,#dbe1ec);border-radius:11px;color:var(--text-secondary);background:var(--bg-card,#fff)}.map-panel-body{padding:20px 24px;display:flex;flex-direction:column;gap:12px;overflow-y:auto;overscroll-behavior:contain;min-height:0}.map-item-card{display:flex;gap:12px;align-items:center;padding:16px;border:1px solid var(--border-glass,#dbe1ec);border-radius:15px;background:var(--bg-card,#fff);color:var(--text-primary);min-height:78px;flex-shrink:0}.map-item-card:hover{border-color:var(--folder-color);background:color-mix(in srgb,var(--folder-color) 4%,var(--bg-card,#fff))}.map-item-icon{width:36px;height:36px;flex:none;border-radius:10px;background:color-mix(in srgb,var(--folder-color) 9%,transparent);color:var(--folder-color);display:grid;place-items:center}.map-item-copy{min-width:0;flex:1}.map-item-copy strong{display:block;font-size:14px;line-height:1.4;overflow-wrap:anywhere}.map-item-copy small{display:block;font-size:11px;color:var(--text-muted);margin-top:4px}.map-item-open{font-size:12px;display:flex;align-items:center;gap:7px;flex:none;color:var(--text-secondary)}.map-panel-footer{display:flex;gap:8px;align-items:center;flex-wrap:wrap;padding:18px 24px;border-top:1px solid var(--border-glass,#dbe1ec);flex-shrink:0;background:var(--bg-card,#fff)}.map-panel-footer .form-chip{font-size:12px;padding:10px 12px}.map-panel-empty{display:grid;justify-items:center;text-align:center;gap:12px;padding:30px 12px}.map-panel-empty>i{font-size:28px;color:var(--folder-color)}.map-panel-empty strong{font-size:15px}.map-panel-empty p{font-size:12px;line-height:1.6;color:var(--text-muted);max-width:34ch}.map-item-card:focus-visible,.map-panel-close:focus-visible{outline:2px solid var(--folder-color);outline-offset:3px}
@media(max-width:640px){.map-panel-backdrop{padding:12px}.map-detail-panel.notes-card,.map-panel-section{max-height:calc(100dvh - 24px)}.map-panel-header{padding:18px;gap:10px}.map-panel-body{padding:16px;gap:10px}.map-panel-footer{padding:14px 16px}.map-item-card{padding:13px;gap:10px}.map-item-open{font-size:0;gap:0}.map-item-open i{font-size:12px}}</style>
<style>
.folder-reports-premium{color:var(--text-primary)}.folder-reports-premium>.folder-panel-head{margin:24px 0 18px}.folder-health-stats{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px;margin-bottom:22px}.folder-health-stat{--ov-tone:#153d80;position:relative;overflow:hidden;min-height:210px;border-radius:24px;padding:23px;background:radial-gradient(ellipse at top right,#5999f3,transparent 80%),#153d80;color:white;box-shadow:inset 0 1px 1px #ffffff66,0 12px 25px #153d8018;display:flex;flex-direction:column;align-items:flex-start}.folder-health-stat:nth-child(2){--ov-tone:#512b80;background:radial-gradient(ellipse at top right,#a075ef,transparent 80%),#512b80}.folder-health-stat:nth-child(3){--ov-tone:#07564f;background:radial-gradient(ellipse at top right,#34aa9e,transparent 80%),#07564f}.folder-health-stat:nth-child(4){--ov-tone:#7d4215;background:radial-gradient(ellipse at top right,#efa928,transparent 80%),#7d4215}.folder-health-stat>span{font-size:14px;font-weight:600;position:relative;z-index:1}.folder-health-stat>svg{position:absolute;right:10px;top:44px;width:78px;height:78px;pointer-events:none}.folder-health-stat>strong{font-size:42px;line-height:1.1;letter-spacing:-1px;margin-top:62px;position:relative;z-index:1}.folder-health-stat>small{font-size:11px;line-height:1.5;opacity:.82;margin-top:10px;position:relative;z-index:1}.folder-health-details{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px;margin-bottom:20px}.folder-health-detail h3,.folder-health-insights h3{font-size:15px;font-weight:700;margin:0 0 16px}.folder-health-detail h3{display:flex;align-items:center;gap:10px}.folder-health-detail h3 i{color:#5472ed}.folder-health-row{display:flex;align-items:center;justify-content:space-between;gap:14px;padding:13px 0;border-top:1px solid var(--border-glass,#e2e8f0)}.folder-health-row>span{min-width:0}.folder-health-row strong{font-size:12px;font-weight:600;display:block}.folder-health-row small{font-size:10px;line-height:1.5;color:var(--text-muted);display:block;margin-top:4px}.folder-health-row b{font-size:19px;flex:none;font-weight:650}.folder-health-insights{display:grid;grid-template-columns:1fr 1fr;gap:18px}.folder-health-insights .notes-hint{margin-bottom:14px}.folder-report-empty{padding:22px 0;color:var(--text-muted);font-size:12px;line-height:1.7;display:grid;gap:10px}.folder-report-empty i{color:#5472ed;font-size:22px}.folder-report-disclosure{padding:16px 2px 0}.folder-health-insights .folder-report-bar{grid-template-columns:minmax(110px,1fr) minmax(50px,1fr) 30px}
@media(max-width:1100px){.folder-health-stats{grid-template-columns:repeat(2,minmax(0,1fr))}.folder-health-details{grid-template-columns:1fr}.folder-health-stat{min-height:190px}}
@media(max-width:640px){.folder-health-stats{gap:10px}.folder-health-stat{padding:16px;border-radius:18px;min-height:190px}.folder-health-stat>strong{font-size:32px;margin-top:58px}.folder-health-stat>span{font-size:12px}.folder-health-stat>svg{width:58px;height:58px;top:43px}.folder-health-stat>small{font-size:10px}.folder-health-insights{grid-template-columns:1fr}}
@media(prefers-reduced-motion:no-preference){.folder-health-stat>svg{animation:folder-art-float 5s ease-in-out infinite}}</style>
<style>.folder-reports-premium>.folder-panel-head h2{font-size:20px;font-weight:750;line-height:1.4;margin:3px 0}</style>
<style>
/* ---- Board viewport: zoom bar, pan surface, fullscreen ------------------ */
.fnet-stage{position:relative;display:flex;flex-direction:column;gap:8px}
.fnet-zoombar{display:flex;align-items:center;gap:8px;flex-wrap:wrap;padding:7px 10px;border:1px solid var(--border-glass);border-radius:14px;background:var(--bg-card,#fff)}
.fnet-zbtn{display:inline-flex;align-items:center;gap:7px;padding:6px 12px;border:1px solid var(--border-glass);border-radius:999px;background:var(--bg-glass-light,#f6f8fd);color:var(--text-secondary);font:inherit;font-size:12.5px;font-weight:650;cursor:pointer;transition:background .15s ease,color .15s ease,border-color .15s ease}
.fnet-zbtn:hover{background:#eaf0ff;border-color:#c6d4ff;color:#2f49c6}
.fnet-zbtn svg{width:15px;height:15px;display:block}
.fnet-zbtn.is-icon{padding:6px;width:30px;justify-content:center}
.fnet-zbtn:focus-visible{outline:2px solid var(--fnet-join,#637cef);outline-offset:2px}
.fnet-zrange{flex:1 1 150px;min-width:110px;max-width:280px;accent-color:var(--fnet-join,#637cef);cursor:pointer}
.fnet-zpct{min-width:46px;text-align:center;font-size:12px;font-weight:700;color:var(--text-muted);font-variant-numeric:tabular-nums}
.fnet-board[data-fnet-view]{overflow:auto;max-height:72vh;overscroll-behavior:contain;cursor:grab;scrollbar-width:thin}
.fnet-board[data-fnet-view].is-panning{cursor:grabbing;user-select:none}
.fnet-sizer{position:relative}
.fnet-canvas[data-fnet-zoom]{transform-origin:0 0;position:absolute;inset:0 auto auto 0;will-change:transform}
.fnet-stage:fullscreen{background:var(--bg-page,#f4f6fb);padding:14px;gap:10px}
.fnet-stage:fullscreen .fnet-board[data-fnet-view]{flex:1 1 auto;max-height:none;height:100%;border-radius:16px}
.fnet-board-people{padding:2px}

/* ---- People / Process cards -------------------------------------------- */
.pcard-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(330px,1fr));gap:18px;padding:4px}
.pcard{--pc:#6366f1;display:flex;flex-direction:column;border-radius:20px;overflow:hidden;background:var(--bg-card,#fff);border:1px solid var(--border-glass);box-shadow:0 14px 34px -24px rgba(31,52,107,.55);transition:transform .16s ease,box-shadow .16s ease}
.pcard:hover{transform:translateY(-2px);box-shadow:0 20px 40px -22px color-mix(in srgb,var(--pc) 55%,transparent)}
.pcard-top{display:flex;align-items:center;gap:12px;padding:16px 18px;color:#fff;background:linear-gradient(145deg,color-mix(in srgb,var(--pc) 92%,#fff),color-mix(in srgb,var(--pc) 58%,#242a5e))}
.pcard-av{position:relative;display:grid;place-items:center;width:46px;height:46px;border-radius:15px;flex:0 0 auto;overflow:hidden;background:#ffffff2e;border:1.6px solid #ffffff5c;font-size:19px;font-weight:800;color:#fff}
.pcard-av img{width:100%;height:100%;object-fit:cover;display:block}
.pcard-id{min-width:0;display:flex;flex-direction:column;gap:2px}
.pcard-id strong{font-size:15px;font-weight:750;letter-spacing:-.01em;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.pcard-id small{font-size:11.5px;font-weight:600;text-transform:uppercase;letter-spacing:.07em;color:#ffffffc7}
.pcard-share{margin-left:auto;display:flex;flex-direction:column;align-items:flex-end;line-height:1.05;font-size:19px;font-weight:800;font-variant-numeric:tabular-nums}
.pcard-share i{font-style:normal;font-size:10px;font-weight:650;letter-spacing:.08em;text-transform:uppercase;color:#ffffffbf}
.pcard-stats{display:grid;grid-template-columns:repeat(4,1fr);gap:1px;background:var(--border-glass)}
.pcard-stats span{display:flex;flex-direction:column;gap:3px;padding:12px 10px;background:var(--bg-card,#fff);font-size:10.5px;font-weight:600;line-height:1.25;color:var(--text-muted)}
.pcard-stats b{font-size:19px;font-weight:780;color:var(--text-primary);font-variant-numeric:tabular-nums}
.pcard-rail{padding:14px 18px 2px}
.pcard-bar{height:7px;border-radius:999px;background:var(--bg-glass-light,#eef2fb);overflow:hidden}
.pcard-bar i{display:block;height:100%;border-radius:inherit;background:linear-gradient(90deg,color-mix(in srgb,var(--pc) 85%,#fff),var(--pc));min-width:0;transition:width .3s ease}
.pcard-legend{display:flex;justify-content:space-between;gap:8px;margin-top:8px;font-size:11.5px;color:var(--text-muted)}
.pcard-legend b{color:var(--text-primary);font-weight:700;font-variant-numeric:tabular-nums}
.pcard-body{padding:8px 18px 16px}
.pcard-row{display:flex;align-items:center;gap:10px;padding:9px 0;border-top:1px solid var(--border-glass);font-size:13px;min-width:0}
.pcard-row i{color:color-mix(in srgb,var(--pc) 70%,#8a93ad);font-size:12px;flex:0 0 auto}
.pcard-row span{min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.pcard-row small{margin-left:auto;white-space:nowrap;font-size:11px;color:var(--text-muted)}
.pcard-row.is-done span{color:var(--text-muted)}
.pcard-row.is-done i{color:#10b981}
.pcard-empty{margin:10px 0 2px;padding:14px;border:1px dashed var(--border-glass);border-radius:12px;text-align:center;font-size:12.5px;color:var(--text-muted)}
@media (max-width:640px){.pcard-grid{grid-template-columns:1fr;gap:14px}.pcard-stats{grid-template-columns:repeat(2,1fr)}.fnet-board[data-fnet-view]{max-height:64vh}.fnet-zrange{flex-basis:100%;max-width:none;order:5}}
</style>
<style>
/* How it works: a specimen beside each note, drawn from the same classes the
   real stations use so the key cannot drift from the board. */
.fnet-guide-grid{grid-template-columns:repeat(auto-fit,minmax(372px,1fr));gap:14px}
.fnet-guide-card{display:flex;align-items:flex-start;gap:14px;padding:15px 16px;border-radius:14px}
.fnet-spec{flex:0 0 auto;display:grid;place-items:center;width:96px;min-height:72px;border-radius:11px;background:var(--bg-glass-light,#f6f8fd);border:1px solid var(--border-glass);padding:8px}
.fnet-spec svg{width:96px;height:46px;display:block;overflow:visible}
.fnet-spec-copy{min-width:0}
.fnet-spec-copy h3{font-size:12.5px;font-weight:700;margin:0 0 5px;letter-spacing:-.01em}
.fnet-spec-copy p{font-size:11.5px;line-height:1.55;color:var(--text-secondary);margin:0}
.fnet-spec-stn{display:flex;flex-direction:column;justify-content:center;gap:1px;width:78px;min-height:58px;padding:8px 9px;border-radius:11px;color:#fff;border:1.2px solid transparent;background:linear-gradient(145deg,color-mix(in srgb,var(--ln) 92%,#fff),color-mix(in srgb,var(--ln) 60%,#242a5e))}
.fnet-spec-stn b{font-size:17px;font-weight:780;line-height:1}
.fnet-spec-stn i{font-style:normal;font-size:7.5px;font-weight:700;letter-spacing:.07em}
.fnet-spec-stn u{text-decoration:none;font-size:6.5px;font-weight:600;opacity:.82;margin-top:2px}
.fnet-spec-stn.is-off{background:var(--bg-card,#fff);border:1.2px dashed var(--border-strong,#cfd6e6);color:var(--text-muted)}
.fnet-spec-stn.is-ai{border-radius:19px}
.fnet-spec-faces{display:flex;align-items:center}
.fnet-spec-faces i{display:grid;place-items:center;width:25px;height:25px;margin-left:-7px;border-radius:50%;background:var(--fnet-create,#3b82f6);color:#fff;border:2px solid var(--bg-card,#fff);font-style:normal;font-size:10px;font-weight:700}
.fnet-spec-faces i:first-child{margin-left:0}
.fnet-spec-faces i:nth-child(2){background:var(--fnet-serve,#0d9488)}
.fnet-spec-faces i:nth-child(3){background:var(--fnet-act,#e0457b)}
.fnet-spec-faces u{text-decoration:none;margin-left:5px;font-size:10.5px;font-weight:700;color:var(--text-muted)}
.fnet-spec-chips{display:flex;flex-direction:column;gap:5px}
.fnet-spec-chips i{font-style:normal;padding:3px 10px;border-radius:999px;border:1px solid var(--border-glass);background:var(--bg-card,#fff);color:var(--text-muted);font-size:9.5px;font-weight:650;text-align:center}
.fnet-spec-chips i.is-on{border-color:color-mix(in srgb,var(--fnet-reach) 55%,transparent);background:color-mix(in srgb,var(--fnet-reach) 13%,#fff);color:color-mix(in srgb,var(--fnet-reach) 72%,#333)}
@media (max-width:640px){
  .fnet-guide-grid{grid-template-columns:1fr}
  .fnet-guide-card{gap:11px;padding:13px}
  .fnet-spec{width:76px;min-height:62px}
  .fnet-spec svg{width:72px;height:40px}
  .fnet-spec-stn{width:62px;min-height:50px;padding:7px}
}
</style>
